mapper.select:
SELECT uwr.*, IF(la.user_hash IS NULL, 0 ,1) last FROM cc_user_work_rel uwr LEFT JOIN ( SELECT user_hash FROM cc_group_user_rel WHERE user_type = #{userType} ORDER BY create_time DESC ) la ON la.user_hash = uwr.user_hash WHERE cc_work_id IN
#{workId}
AND uwr.tenant_id = #{tenantId} AND uwr.user_type = #{userType} ORDER BY COALESCE(uwr.sort_num, uwr.id), uwr.id
